/* persistence.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "./context.js";

export function install(P) {


  /* ---------- persistence ---------- */

  function loadSaved() {
    try {
      const raw = localStorage.getItem(P.STORAGE_STATE);
      if (raw) return JSON.parse(raw) || {};
      const legacy = localStorage.getItem(P.STORAGE_SETTINGS);
      return legacy ? JSON.parse(legacy) || {} : {};
    } catch { return {}; }
  }

  function saveState() {
    try {
      // Imported remixes are session-only blob URLs: persisting them would
      // restore a dead URL on the next visit.
      const transient = !!P.state.current && String(P.state.current.path).startsWith("blob:");
      const current = transient ? null : P.state.current;
      const context = transient ? null : P.state.context;
      const payload = {
        ...P.state,
        current,
        context,
        queue: P.state.queue.filter((item) => !String(item.path || "").startsWith("blob:")),
        time: P.state.rememberPosition && current ? P.audio.currentTime || 0 : 0,
      };
      localStorage.setItem(P.STORAGE_STATE, JSON.stringify(payload));
      localStorage.setItem(P.STORAGE_SETTINGS, JSON.stringify({
        volume: P.state.volume, muted: P.state.muted, shuffle: P.state.shuffle,
        repeat: P.state.repeat, engine: P.state.engine, format: P.state.format,
        engineExplicit: P.state.engineExplicit,
        autoNext: P.state.autoNext, rememberPosition: P.state.rememberPosition,
        crossfade: P.state.crossfade, fadeOutMs: P.state.fadeOutMs, fadeInMs: P.state.fadeInMs,
        fadeOutEnabled: P.state.fadeOutEnabled, fadeInEnabled: P.state.fadeInEnabled,
        skipIntro: P.state.skipIntro, silenceDb: P.state.silenceDb, introMaxSec: P.state.introMaxSec,
        playbackRate: P.state.playbackRate, preservePitch: P.state.preservePitch, playbackMode: P.state.playbackMode, pitchMode: P.state.pitchMode,
        eqEnabled: P.state.eqEnabled, eqFilters: P.state.eqFilters,
        limiterEnabled: P.state.limiterEnabled !== false, limiterMode: P.state.limiterMode,
        fxBakeDelayMs: P.state.fxBakeDelayMs, remixFormat: P.state.remixFormat,
        ...Object.fromEntries(P.FX_KINDS.map((kind) => [`${kind}Enabled`, P.state[`${kind}Enabled`]])),
        ...Object.fromEntries(Object.keys(P.FX_RANGES).map((key) => [key, P.state[key]])),
      }));
      if (context?.albumId) localStorage.setItem(P.STORAGE_ALBUM, context.albumId);
    } catch {}
  }

  function saveStateSoon() {
    if (P.saveTimer) return;
    P.saveTimer = window.setTimeout(() => { P.saveTimer = 0; P.saveState(); }, 1500);
  }
  Object.assign(P, { loadSaved, saveState, saveStateSoon });
}
